  container.querySelectorAll('[data-source-tab]').forEach(b=>b.onclick=()=>{d.filters={...readFilters(form,d.filters),source:b.dataset.sourceTab,paperId:''};d.searched=false;d.selected.clear();redraw();});
  const setStep=step=>{if(search&&form)d.filters=readFilters(form,d.filters);d.tab=step;d.selected.clear();d.issuedView='questions';redraw();window.scrollTo(0,0);};
  container.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{if(b.dataset.step==='edit'&&search&&d.selected.size)return container.querySelector('#pp-next')?.click();if(b.dataset.step==='edit'&&!paper.questionIds.length)return ctx.ui.toast('문항을 선택한 뒤 다음 단계로 진행해 주세요.');setStep(b.dataset.step);});
